	"sdk/component-ui/cn.ts": "// Package-owned class-name helper for component-ui primitives. Mirrors the\r\n// shadcn-vue `cn` utility so package primitives never reach into the host app's\r\n// `@/lib/utils`.\r\n\r\nimport type { ClassValue } from \"clsx\";\r\nimport { clsx } from \"clsx\";\r\nimport { twMerge } from \"tailwind-merge\";\r\n\r\nexport function cn(...inputs: ClassValue[]) {\r\n  return twMerge(clsx(inputs));\r\n}\r\n",
	"sdk/component-ui/collapsible/Collapsible.vue": "<script setup lang=\"ts\">\r\nimport type { CollapsibleRootEmits, CollapsibleRootProps } from \"reka-ui\";\r\nimport { CollapsibleRoot, useForwardPropsEmits } from \"reka-ui\";\r\n\r\nconst props = defineProps<CollapsibleRootProps>();\r\nconst emits = defineEmits<CollapsibleRootEmits>();\r\n\r\nconst forwarded = useForwardPropsEmits(props, emits);\r\n<\/script>\r\n\r\n<template>\r\n  <CollapsibleRoot v-slot=\"slotProps\" data-slot=\"collapsible\" v-bind=\"forwarded\">\r\n    <slot v-bind=\"slotProps\" />\r\n  </CollapsibleRoot>\r\n</template>\r\n",
